function equal(a,b,k){if(a==null||b==null)return a===b;const clean=v=>String(v).replace(/\r\n?/g,'\n');if(k==='categories'){const norm=v=>[...new Set(clean(v).split(';').map(x=>x.trim()).filter(Boolean))].sort();return JSON.stringify(norm(a))===JSON.stringify(norm(b));}return clean(a)===clean(b);}
